// Using Playwright
import { test, expect } from '@playwright/test';

test('complete onboarding flow', async ({ page }) => {
  // Seed deterministic test data
  await seedTestUser({ email: 'demo@test.com', password: 'Test123!' });

  // Mock email service to capture verification link
  await mockEmailService();

  // Mock OIDC provider
  await mockOIDCProvider();

  // Navigate to signup and complete registration
  await page.goto('/signup');
  await page.fill('[name=email]', 'demo@test.com');
  await page.fill('[name=password]', 'Test123!');
  await page.click('[data-testid=signup-submit]');

  // Extract and follow email verification link
  const verifyLink = await getVerificationLink('demo@test.com');
  await page.goto(verifyLink);

  // Complete profile setup
  await page.fill('[name=name]', 'Jane Doe');
  await page.fill('[name=company]', 'Acme Corp');
  await page.click('[data-testid=profile-submit]');

  // Create first workspace
  await page.fill('[name=workspaceName]', 'My Workspace');
  await page.click('[data-testid=create-workspace]');

  // Assert dashboard displays new workspace
  await expect(page.locator('[data-testid=workspace-card]')).toContainText('My Workspace');
});
